sys_ui_page.client_script:
function loadIncidents(keyword) {
    var ga = new GlideAjax('x_938076_now_utils.OptionProcessorAjax');
    ga.addParam('sysparm_name', 'getIncidents');
    ga.addParam('sysparm_keyword', keyword);
    ga.getXMLAnswer(function(response) {
        var incidents = JSON.parse(response);
        var tbody = $('#incidentsTable tbody');
        tbody.empty();

        incidents.forEach(function(inc) {
            var row = `
                <tr>
                    <td><input type="checkbox" class="incSelect" data-sysid="${inc.sys_id}"/></td>
                    <td>${inc.number}</td>
                    <td>${inc.short_description}</td>
                    <td>${inc.comments}</td>
                    <td>${inc.additional_comments}</td>
                </tr>
            `;
            tbody.append(row);
        });
    });
}

function updateSelectedComments() {
    var selected = [];
    $('input.incSelect:checked').each(function() {
        selected.push($(this).data('sysid'));
    });

    var comment = $('#updateComments').val().trim();

    if (selected.length === 0) {
        alert('Please select at least one incident.');
        return;
    }

    if (!comment) {
        alert('Please enter a comment to update.');
        return;
    }

    var ga = new GlideAjax('x_938076_now_utils.OptionProcessorAjax');
    ga.addParam('sysparm_name', 'updateComments');
    ga.addParam('sysparm_sys_ids', selected.join(','));
    ga.addParam('sysparm_comment', comment);
    ga.getXMLAnswer(function(response) {
        alert(response);
        loadIncidents('');
        $('#updateComments').val('');
    });
}

$(document).ready(function() {
    loadIncidents('');

    $('#btnSearch').click(function() {
        var keyword = $('#searchBox').val().trim();
        loadIncidents(keyword);
    });

    $('#btnClear').click(function() {
        $('#searchBox').val('');
        loadIncidents('');
    });

    $('#btnUpdate').click(function() {
        updateSelectedComments();
    });

    $('#selectAll').click(function() {
        var checked = $(this).is(':checked');
        $('input.incSelect').prop('checked', checked);
    });
});
